// Matched-count diagnostic driver. Original published executables stay intact.
#include "harness.h"
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>

static double now_ns() {
  return static_cast<double>(std::chrono::duration_cast<std::chrono::nanoseconds>(
      std::chrono::steady_clock::now().time_since_epoch()).count());
}

static void counter_command(FILE *control, FILE *ack, const char *command) {
  if (!control) return;
  char answer[64];
  if (std::fprintf(control, "%s\n", command) < 0 || std::fflush(control) != 0) std::exit(3);
  unsigned count = 0;
  for (;;) {
    const int byte = std::fgetc(ack);
    if (byte == EOF || count >= sizeof answer - 1) std::exit(3);
    // perf appends a NUL after ack\n, which can prefix the next message.
    if (byte == 0) continue;
    answer[count++] = static_cast<char>(byte);
    if (byte == '\n') break;
  }
  answer[count] = 0;
  if (std::strcmp(answer, "ack\n") != 0) {
    std::fputs("counter acknowledgement failed\n", stderr);
    std::exit(3);
  }
}

int main() {
  const char *count_text = std::getenv("NTS_BENCH_COUNT_N");
  char *end = nullptr;
  const long n = count_text ? std::strtol(count_text, &end, 10) : 0;
  if (!end || *end || n < 1 || n > 50000000) return 2;
  const char *control_path = std::getenv("NTS_BENCH_COUNT_CONTROL");
  const char *ack_path = std::getenv("NTS_BENCH_COUNT_ACK");
  if ((control_path == nullptr) != (ack_path == nullptr)) return 2;
  FILE *control = control_path ? std::fopen(control_path, "w") : nullptr;
  FILE *ack = ack_path ? std::fopen(ack_path, "r") : nullptr;
  if (control_path && (!control || !ack)) return 2;
  const double checksum = bench_run();
  volatile double sink = checksum;
  counter_command(control, ack, "enable");
  const double start = now_ns();
  for (long i = 0; i < n; i++) sink = sink + bench_run();
  const double elapsed = now_ns() - start;
  counter_command(control, ack, "disable");
  if (control) std::fclose(control);
  if (ack) std::fclose(ack);
  const double result = sink;
  if (!std::isfinite(checksum) || !std::isfinite(result) || elapsed <= 0) return 4;
  std::uint64_t bits;
  std::memcpy(&bits, &checksum, sizeof bits);
  std::printf("{\"n\":%ld,\"warmup\":1,\"checksum\":\"%016llx\",\"nsPerOp\":%.17g,\"elapsedNs\":%.17g,\"sink\":%.17g}\n",
      n, static_cast<unsigned long long>(bits), elapsed / static_cast<double>(n), elapsed, result);
  return 0;
}

